import { useEffect, useRef, useState } from 'react'
import type { ReactNode } from 'react'
import './styles.css'

export interface CanvasViewport {
  zoom: number
  offsetX: number
  offsetY: number
}

export interface CanvasProps {
  children?: ReactNode
  label: string
  initialZoom?: number
  minZoom?: number
  maxZoom?: number
  gridSize?: number
  snapToGrid?: boolean
  showMinimap?: boolean
  onViewportChange?: (viewport: CanvasViewport) => void
  className?: string
}

/** Snaps a world coordinate to the nearest grid intersection when enabled. */
export function snapToGridValue(value: number, gridSize: number, enabled: boolean) {
  if (!enabled || gridSize <= 0) return value
  return Math.round(value / gridSize) * gridSize
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value))
}

export function Canvas({
  children,
  label,
  initialZoom = 1,
  minZoom = 0.25,
  maxZoom = 2,
  gridSize = 24,
  snapToGrid = false,
  showMinimap = false,
  onViewportChange,
  className,
}: CanvasProps) {
  const [viewport, setViewport] = useState<CanvasViewport>({ zoom: clamp(initialZoom, minZoom, maxZoom), offsetX: 0, offsetY: 0 })
  const [panning, setPanning] = useState(false)
  const gridRef = useRef<HTMLCanvasElement>(null)
  const minimapRef = useRef<HTMLCanvasElement>(null)
  const dragOrigin = useRef<{ pointerX: number; pointerY: number; offsetX: number; offsetY: number } | null>(null)
  const classes = ['cu-canvas', className].filter(Boolean).join(' ')

  const applyViewport = (next: CanvasViewport) => {
    const clamped = { zoom: clamp(next.zoom, minZoom, maxZoom), offsetX: next.offsetX, offsetY: next.offsetY }
    setViewport(clamped)
    onViewportChange?.(clamped)
  }

  // Canvas 2D grid backend: draws the world grid; degrades to a plain surface when 2D is unavailable (e.g. jsdom).
  useEffect(() => {
    const element = gridRef.current
    if (!element) return
    let context: CanvasRenderingContext2D | null = null
    try {
      context = element.getContext('2d')
    } catch {
      context = null
    }
    if (!context) return
    const width = (element.clientWidth || 800)
    const height = (element.clientHeight || 600)
    if (element.width !== width) element.width = width
    if (element.height !== height) element.height = height
    const styles = getComputedStyle(element)
    const gridColor = styles.getPropertyValue('--cu-color-border-default').trim() || 'gray'
    context.clearRect(0, 0, width, height)
    context.strokeStyle = gridColor
    context.globalAlpha = 0.4
    context.lineWidth = 1
    const step = gridSize * viewport.zoom
    if (step < 4) return
    const startX = ((viewport.offsetX % step) + step) % step
    const startY = ((viewport.offsetY % step) + step) % step
    context.beginPath()
    for (let x = startX; x <= width; x += step) {
      context.moveTo(x, 0)
      context.lineTo(x, height)
    }
    for (let y = startY; y <= height; y += step) {
      context.moveTo(0, y)
      context.lineTo(width, y)
    }
    context.stroke()
    context.globalAlpha = 1
  }, [viewport, gridSize])

  useEffect(() => {
    const element = minimapRef.current
    if (!element || !showMinimap) return
    let context: CanvasRenderingContext2D | null = null
    try {
      context = element.getContext('2d')
    } catch {
      context = null
    }
    if (!context) return
    const width = element.width
    const height = element.height
    const styles = getComputedStyle(element)
    const frameColor = styles.getPropertyValue('--cu-color-border-default').trim() || 'gray'
    const viewportColor = styles.getPropertyValue('--cu-color-palette-brand').trim() || frameColor
    context.clearRect(0, 0, width, height)
    context.strokeStyle = frameColor
    context.strokeRect(0, 0, width - 1, height - 1)
    // Viewport indicator: the visible world window mapped into minimap scale.
    const scaleX = width / 4000
    const scaleY = height / 3000
    context.strokeStyle = viewportColor
    context.strokeRect(-viewport.offsetX * scaleX, -viewport.offsetY * scaleY, 800 * scaleX * viewport.zoom, 600 * scaleY * viewport.zoom)
  }, [viewport, showMinimap])

  const onPointerDown = (event: React.PointerEvent<HTMLDivElement>) => {
    if ((event.target as HTMLElement).closest('[data-canvas-node]')) return
    dragOrigin.current = { pointerX: event.clientX, pointerY: event.clientY, offsetX: viewport.offsetX, offsetY: viewport.offsetY }
    setPanning(true)
  }

  const onPointerMove = (event: React.PointerEvent<HTMLDivElement>) => {
    const origin = dragOrigin.current
    if (!origin) return
    const nextX = origin.offsetX + (event.clientX - origin.pointerX)
    const nextY = origin.offsetY + (event.clientY - origin.pointerY)
    applyViewport({
      zoom: viewport.zoom,
      offsetX: snapToGridValue(nextX, gridSize, snapToGrid),
      offsetY: snapToGridValue(nextY, gridSize, snapToGrid),
    })
  }

  const endPan = () => {
    dragOrigin.current = null
    setPanning(false)
  }

  const onWheel = (event: React.WheelEvent<HTMLDivElement>) => {
    const factor = event.deltaY < 0 ? 1.1 : 1 / 1.1
    applyViewport({ ...viewport, zoom: viewport.zoom * factor })
  }

  const onKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    const panStep = gridSize * 4
    if (event.key === 'ArrowLeft') applyViewport({ ...viewport, offsetX: viewport.offsetX + panStep })
    else if (event.key === 'ArrowRight') applyViewport({ ...viewport, offsetX: viewport.offsetX - panStep })
    else if (event.key === 'ArrowUp') applyViewport({ ...viewport, offsetY: viewport.offsetY + panStep })
    else if (event.key === 'ArrowDown') applyViewport({ ...viewport, offsetY: viewport.offsetY - panStep })
    else if (event.key === '+' || event.key === '=') applyViewport({ ...viewport, zoom: viewport.zoom * 1.1 })
    else if (event.key === '-') applyViewport({ ...viewport, zoom: viewport.zoom / 1.1 })
    else return
    event.preventDefault()
  }

  return (
    <div
      className={classes}
      role="application"
      aria-label={label}
      aria-description={`Zoom ${Math.round(viewport.zoom * 100)}%`}
      tabIndex={0}
      data-ai-role="canvas-base" data-ai-intent="pan-canvas"
      data-ai-state={panning ? 'panning' : 'default'}
      data-backend="canvas-2d"
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={endPan}
      onPointerLeave={endPan}
      onWheel={onWheel}
      onKeyDown={onKeyDown}
    >
      <canvas ref={gridRef} className="cu-canvas__grid" width={800} height={600} aria-hidden="true" />
      <div
        className="cu-canvas__world"
        style={{ transform: `translate(${viewport.offsetX}px, ${viewport.offsetY}px) scale(${viewport.zoom})` }}
      >
        {children}
      </div>
      {showMinimap ? <canvas ref={minimapRef} className="cu-canvas__minimap" width={160} height={120} aria-hidden="true" /> : null}
    </div>
  )
}

{
  "schemaVersion": "0.2",
  "slug": "canvas-base",
  "name": "Canvas",
  "family": "G",
  "status": "experimental",
  "purpose": "Zoomable and pannable canvas base with minimap and grid snapping; Canvas 2D grid backend with a DOM node layer.",
  "scenarios": [
    "Host a flow editor",
    "Pan across a large diagram",
    "Zoom into a dense graph with minimap orientation"
  ],
  "props": {
    "children": {
      "type": "node",
      "required": false,
      "description": "Canvas items rendered inside the transformed world layer."
    },
    "label": {
      "type": "string",
      "required": true,
      "description": "Accessible label for the canvas region."
    },
    "initialZoom": {
      "type": "number",
      "required": false,
      "description": "Initial zoom factor.",
      "default": 1
    },
    "minZoom": {
      "type": "number",
      "required": false,
      "description": "Smallest zoom factor.",
      "default": 0.25
    },
    "maxZoom": {
      "type": "number",
      "required": false,
      "description": "Largest zoom factor.",
      "default": 2
    },
    "gridSize": {
      "type": "number",
      "required": false,
      "description": "Grid cell size in world px.",
      "default": 24
    },
    "snapToGrid": {
      "type": "boolean",
      "required": false,
      "description": "Snap world coordinates to the grid.",
      "default": false
    },
    "showMinimap": {
      "type": "boolean",
      "required": false,
      "description": "Render the minimap overview.",
      "default": false
    },
    "onViewportChange": {
      "type": "event",
      "required": false,
      "description": "Called with { zoom, offsetX, offsetY } on every pan or zoom."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Canvas idle at rest."
    },
    {
      "name": "panning",
      "description": "User is dragging the viewport."
    }
  ],
  "composition": {
    "allowedParents": [
      "page",
      "app-shell"
    ],
    "allowedChildren": [
      "flow-node",
      "edge",
      "canvas-toolbar"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not nest one canvas inside another.",
    "Do not claim WebGL or worker rendering; the backend is Canvas 2D plus DOM."
  ],
  "a11y": {
    "role": "application",
    "keyboard": [
      "Arrow keys pan the viewport",
      "Plus and minus keys zoom"
    ],
    "focus": "Canvas region is focusable; interactive nodes keep their own tab order.",
    "labeling": "aria-label names the canvas; zoom level is announced via aria-description.",
    "wcag": [
      "2.1.1",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "Fills the parent region; minimap hides on compact.",
    "breakpoints": {
      "compact": "No minimap; touch pan only.",
      "medium": "Minimap visible.",
      "large": "Minimap visible."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "canvas-base",
    "states": [
      "default",
      "panning"
    ],
    "intents": [
      "pan-canvas"
    ]
  }
}

.cu-canvas {
  position: relative;
  display: block;
  inline-size: 100%;
  min-block-size: calc(var(--cu-space-3) * 24);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
  overflow: hidden;
  touch-action: none;
}

.cu-canvas:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
}

.cu-canvas__grid {
  position: absolute;
  inset: 0;
  inline-size: 100%;
  block-size: 100%;
}

.cu-canvas__world {
  position: absolute;
  inset: 0;
  transform-origin: 0 0;
}

[dir='rtl'] .cu-canvas__world {
  transform-origin: 100% 0;
}

.cu-canvas__minimap {
  position: absolute;
  inset-inline-end: var(--cu-space-2);
  inset-block-end: var(--cu-space-2);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-sm);
  background: var(--cu-color-background-default);
}
